    def kernel(x_ref):
        x_ref[()] = jnp.sign(x_ref[()])

    x = jnp.array(jnp.nan, dtype=jnp.float32)
    result = pallas.gpu.pallas_call(kernel, out_shape=jax.ShapeDtypeStruct(shape=(), dtype=jnp.float32))(x)
